<?php
use App\Models\{Project,RepositoryConnection,DevelopmentEvent,Automation,Ticket};
use App\Services\DevelopmentPayload;
use App\Core\{DB,Security};

$gitProject=Project::save(['name'=>'Suivi Git A','key'=>'GA'.strtoupper(bin2hex(random_bytes(3)))]);
$otherGitProject=Project::save(['name'=>'Suivi Git B','key'=>'GB'.strtoupper(bin2hex(random_bytes(3)))]);
$gitConnection=DB::insert('INSERT INTO connections(project_id,provider,repository,secret_cipher,webhook_cipher) VALUES(?,?,?,?,?)',[$gitProject,'github','organisation/projet-tests',Security::encrypt('synthetic-git-token'),Security::encrypt('synthetic-git-hook')]);
$gitC=DB::one('SELECT * FROM connections WHERE id=?',[$gitConnection]);
Project::save(['repository_connection_id'=>$gitConnection],$gitProject);
Project::save(['repository_connection_id'=>$gitConnection],$otherGitProject);
check(Project::find($otherGitProject)['repository_connection_id']===$gitConnection && count(RepositoryConnection::forProject($otherGitProject))===1,'même connexion Git partagée entre deux projets sans copie de jeton');
rejects(fn()=>Project::save(['repository_connection_id'=>'not-an-id'],$gitProject),'sélection de dépôt invalide refusée');
$gitA=Ticket::create($gitProject,['title'=>'Premier ticket Git'],$uid);
$gitA2=Ticket::create($gitProject,['title'=>'Second ticket Git'],$uid);
$gitB=Ticket::create($otherGitProject,['title'=>'Ticket partagé'],$uid);
$gitKey=Ticket::find($gitA)['key']; $gitKey2=Ticket::find($gitA2)['key']; $gitKeyB=Ticket::find($gitB)['key'];
Automation::save(['project_id'=>$gitProject,'name'=>'Démarrer à la création de branche','event'=>'development.branch_created','actions'=>['status'=>'progress']],$uid);
$branch=DevelopmentPayload::object('github','branch',['name'=>'feature/'.$gitKey.'-test','created'=>true],'organisation/projet-tests',true);
$branchId=DevelopmentEvent::save($gitC,$branch,true);
check(Ticket::find($gitA)['status']==='progress','création de branche signale la règle configurée');
DevelopmentEvent::save($gitC,$branch,true);
check((int)DB::one('SELECT COUNT(*) n FROM automation_runs WHERE ticket_id=?',[$gitA])['n']===1,'livraison répétée sans réexécution de la règle Git');
$sha=str_repeat('a',40);
$commit=DevelopmentPayload::object('github','commit',['sha'=>$sha,'commit'=>['message'=>$gitKey.' '.$gitKey2.' '.$gitKeyB.' Correction','author'=>['date'=>'2026-10-28T09:00:00Z']]],'organisation/projet-tests');
$commitId=DevelopmentEvent::save($gitC,$commit);
check((int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=?',[$commitId])['n']===3,'un commit associé à tous les tickets de plusieurs projets liés');
$mainBranch=DevelopmentEvent::save($gitC,DevelopmentPayload::object('github','branch',['name'=>'main','commit'=>['sha'=>$sha]],'organisation/projet-tests'));
check((int)DB::one('SELECT COUNT(*) n FROM development_event_tickets WHERE event_id=?',[$mainBranch])['n']===0,'branche générique sans clé de ticket non attribuée par simple partage de SHA');
$hydrated=DevelopmentEvent::withTickets([DB::one('SELECT * FROM development_events WHERE id=?',[$commitId])],$otherGitProject);
check(count($hydrated[0]['ticket_refs'])===1 && $hydrated[0]['ticket_refs'][0]['key']===$gitKeyB,'références présentées dans le contexte du projet demandé');
Automation::save(['project_id'=>$gitProject,'name'=>'Revue après fusion','event'=>'development.pull_request_merged','conditions'=>['development_repository'=>'organisation/projet-tests'],'actions'=>['status'=>'review']],$uid);
$pr=['number'=>15,'title'=>$gitKey.' Correction','state'=>'open','head'=>['ref'=>'feature/'.$gitKey,'sha'=>$sha],'html_url'=>'https://github.com/organisation/projet-tests/pull/15','updated_at'=>'2026-10-28T10:00:00Z'];
$prId=DevelopmentEvent::save($gitC,DevelopmentPayload::object('github','pull_request',$pr,'organisation/projet-tests'));
$pr['state']='closed';$pr['merged']=true;$pr['updated_at']='2026-10-28T11:00:00Z';
$merged=DevelopmentPayload::object('github','pull_request',$pr,'organisation/projet-tests',true,null,'closed');
DevelopmentEvent::save($gitC,$merged,true);
check(Ticket::find($gitA)['status']==='review' && Ticket::find($gitA2)['status']==='review' && Ticket::find($gitB)['status']==='todo','fusion applique les règles des projets concernés sans modifier les autres');
$runs=(int)DB::one('SELECT COUNT(*) n FROM automation_runs WHERE event_name=?',['development.pull_request_merged'])['n'];
DevelopmentEvent::save($gitC,$merged,true);
check((int)DB::one('SELECT COUNT(*) n FROM automation_runs WHERE event_name=?',['development.pull_request_merged'])['n']===$runs,'fusion répétée idempotente');
$pr['merged']=false;$pr['state']='open';$pr['updated_at']='2026-10-28T08:00:00Z';
DevelopmentEvent::save($gitC,DevelopmentPayload::object('github','pull_request',$pr,'organisation/projet-tests',true,null,'opened'),true);
check(DB::one('SELECT state FROM development_events WHERE id=?',[$prId])['state']==='merged','notification plus ancienne sans régression de l’état');
$historyTicket=Ticket::create($gitProject,['title'=>'Historique'],$uid);
$history=['number'=>16,'title'=>Ticket::find($historyTicket)['key'].' Ancienne fusion','state'=>'closed','merged'=>true,'updated_at'=>'2026-10-27T11:00:00Z'];
DevelopmentEvent::save($gitC,DevelopmentPayload::object('github','pull_request',$history,'organisation/projet-tests'));
check(Ticket::find($historyTicket)['status']==='todo','import historique sans déplacement automatique des tickets');
$bb=DevelopmentPayload::webhook('bitbucket','pullrequest:fulfilled',['pullrequest'=>['id'=>3,'title'=>'Correction','state'=>'MERGED','source'=>['branch'=>['name'=>'feature/'.$gitKey]]]],'espace/projet');
check($bb[0]['state']==='merged' && $bb[0]['trigger']==='development.pull_request_merged','état de fusion Bitbucket reconnu');
rejects(fn()=>DevelopmentPayload::webhook('github','pull_request',['pull_request'=>'invalid'],'organisation/projet-tests'),'payload de pull request malformé refusé');
RepositoryConnection::detach($gitProject,$gitConnection);
check(DB::one('SELECT id FROM connections WHERE id=?',[$gitConnection])!==null && Project::find($gitProject)['repository_connection_id']===null && count(RepositoryConnection::forProject($otherGitProject))===1,'détacher un projet conserve la connexion des autres projets');
$emptyOrigin=Project::save(['name'=>'Origine vide','key'=>'GO'.strtoupper(bin2hex(random_bytes(3)))]);
$sharedOrigin=DB::insert('INSERT INTO connections(project_id,provider,repository,secret_cipher,webhook_cipher) VALUES(?,?,?,?,?)',[$emptyOrigin,'github','organisation/provenance',Security::encrypt('synthetic-origin-token'),Security::encrypt('synthetic-origin-hook')]);
RepositoryConnection::attach($emptyOrigin,$sharedOrigin); RepositoryConnection::attach($otherGitProject,$sharedOrigin);
rejects(fn()=>Project::deleteEmpty($emptyOrigin),'suppression d’un projet encore lié à un dépôt refusée');
RepositoryConnection::detach($emptyOrigin,$sharedOrigin); Project::deleteEmpty($emptyOrigin);
check(DB::one('SELECT project_id FROM connections WHERE id=?',[$sharedOrigin])['project_id']===null && count(RepositoryConnection::forProject($otherGitProject))===2,'suppression du projet d’origine sans supprimer la connexion partagée');
